12	const name = 'meterwatch';
13	
14	const help = `${name}
15	
16	建筑能耗监测:本地累计电表读数导入与消耗核查。
17	
18	Usage:
19	  node app.ts                       显示本帮助
20	  node app.ts --help | -h           显示本帮助
21	  node app.ts import <file.csv>     导入 CSV 读数(整批成功或整批拒绝)
22	  node app.ts readings [筛选...]    查询读数、区间与消耗
23	  node app.ts daily --from <iso> --to <iso> [--device <id>...] [--tz <时区>]
24	                                    按当地自然日核查能耗的只读日报(默认 UTC 分日)
25	  node app.ts rule create --id <id> (--device <设备> | --group <分组>) --threshold <kWh> [--tz <时区>]
26	                                    创建每日能耗阈值告警规则(设备或分组,时区省略为 UTC)
27	  node app.ts rule list             查看全部告警规则
28	  node app.ts evaluate --rule <id> --from <日期> --to <日期>
29	                                    评估规则在连续完整当地日期(按规则时区)上的超限情况
30	  node app.ts alerts --rule <id> [--from <日期> --to <日期>]
31	                                    查询规则的告警历史(只读)
32	  node app.ts ack <告警标识>         确认告警
33	  node app.ts group configure --id <id> --at <iso> --device <id>...
34	                                    配置分组成员版本(首次配置即建立分组)
35	  node app.ts group history --id <id>
36	                                    查看分组成员版本历史(只读)
37	  node app.ts group daily --id <id> --from <iso> --to <iso> [--tz <时区>]
38	                                    按当时生效成员的分组能耗日报(只读,默认 UTC 分日)
39	  node app.ts correct --request <id> --item --device <设备> --at <iso> --expect <kWh> --set <kWh>
40	                                    [--item --device ... --at ... --expect ... --set ...]...
41	                                    批量修正已存读数的累计值(整批成功或整批拒绝)
42	  node app.ts undo --request <id> --target <修正请求标识>
43	                                    整批撤销一次已成功修正(恢复实际改变过的读数)
44	  node app.ts corrections             查看修正与撤销历史(只读)
45	  node app.ts backup <快照文件>       导出全库快照(快照文件须位于数据目录之外,已存在则拒绝)
46	  node app.ts restore <快照文件>      从快照整库恢复(三个业务存储作为一次提交整体替换)
47	
48	备份与恢复(backup / restore):
49	  backup 把当前数据目录的三个业务存储(读数与修正/撤销历史、告警规则与历史、
50	  分组成员版本)连同后续编号状态完整导出为一个快照文件,任意大数精确保留;
51	  快照带格式版本与 SHA-256 完整性校验。快照文件必须位于数据目录之外,已存在
52	  的输出文件拒绝覆盖;备份只读取业务数据,不改写。restore 不解析当前库(可用于
53	  当前存储已损坏的目录),先校验快照的版本、完整性与三个存储的结构和关联
54	  (全库重复读数身份、修正项引用缺失读数、撤销引用缺失修正、成员或规则目标
55	  不存在、告警引用缺失规则,任一问题指出原因并拒绝),再把三个业务存储作为
56	  一次提交整体替换:成功后业务状态完全等于快照,快照为空的部分清除原数据,
57	  快照之后新增的读数、请求和告警不保留,目录内其他文件保持不变,不自动评估
58	  或重新生成历史。读写或重命名失败保留恢复前全部状态;进程在提交中断后,任一
59	  命令再次启动会先恢复为完整旧状态或完整快照状态,绝不使用混合状态。备份与
60	  恢复执行期间对数据目录持有排他锁,不与其他进程同时读写同一目录。
61	
62	筛选(readings):
63	  --device <id>     只显示指定设备(可重复使用,区分大小写)
64	  --from <iso8601>  起始时刻(含),如 2026-01-01T00:00:00Z
65	  --to <iso8601>    结束时刻(不含)
66	  省略边界表示不限;时间必须为秒精度 ISO8601 且带 Z 或数字时区偏移
67	  (如 +08:00);起点不早于终点时拒绝查询。
68	
69	日报(daily):
70	  --from <iso8601>  起始时刻(含),必填
71	  --to <iso8601>    结束时刻(不含),必填,必须晚于起点
72	  --device <id>     只统计指定设备(可重复使用);省略时统计库内全部设备
73	  --tz <时区>       分日时区(IANA 名,如 Asia/Shanghai);省略时按 UTC
74	  日期按分日时区的当地零点划分,首尾日期只统计与查询范围重叠的部分。
75	  估算口径:由每个设备完整时序的相邻读数构成区间,区间两端读数即使在
76	  查询范围外也参与;非下降区间把累计值之差按持续时间均匀分摊,以千分之一
77	  kWh 为单位,从区间起点累计到切点(查询边界与日界线)向下取整,片段消耗
78	  为两端累计量之差,故完整区间的分摊总量等于原差值,同一区间拆开查询再
79	  相加结果一致。下降区间不分摊,记为异常覆盖;首条读数之前、末条之后及
80	  孤立读数时段为未知,不外推。每天输出估算消耗与有效/异常/未知覆盖秒数
81	  (三者之和等于该天实际统计的各 UTC 时段总秒数),并标明所用时区与各
82	  UTC 时段;存在未知或异常覆盖时日报标记为不完整。日报只读,不写入数据。
83	
84	分日时区(--tz,daily 与 group daily 可选):
85	  接受运行环境支持的 IANA 时区名(如 Asia/Shanghai、America/New_York);
86	  未知时区名为参数错误,返回 2。时区只决定分日,不重新解释输入时刻或
87	  已存读数。日界线按实际时刻的当地日期归属计算,不按固定 86400 秒或
88	  全年固定偏移推算:夏令时前拨跳过的当天更短(跳过的小时不存在,不补
89	  为未知),回拨当天更长(重复小时按各自实际时刻完整计入);同一当地
90	  日期的不连续时段合并统计、分别列出;没有实际时段的当地日期不生成
91	  日报。日界线不重置分摊起点,拆开查询再相加与整段一致。
92	
93	分组(group configure / history / daily):
94	  分组以首次 configure 建立,标识非空唯一(去首尾空白、区分大小写)。
95	  configure 的 --at 为版本生效时刻(含,秒精度 ISO8601 带 Z 或数字时区
96	  偏移),--device 给出一整套已有设备(至少一个,可重复;同设备重复列出
97	  只算一次,成员顺序不影响等价性,设备可属于多个分组);版本从生效时刻起
98	  生效直到下一版本接替,允许乱序补录历史版本。同组同一实际生效时刻、同
99	  成员集合重试成功且不新增,异成员集合报冲突;未知设备报错,配置整次成功
100	  或不提交。history 按生效时刻列出全部版本(只读)。daily 的 --from(含)
101	  与 --to(不含)必填且起点必须更早,按分日时区的自然日切分(--tz 可选,
102	  默认 UTC,口径见上文"分日时区"),按当时生效成员计算,首个版本生效前
103	  记为未知;每个时段只有全部生效成员均处于非下降读数
104	  区间才是有效覆盖并计入成员消耗之和,任一成员下降为异常,否则任一成员
105	  未知为未知;异常与未知时段不计任何成员消耗,覆盖秒数按分组实际时间计;
106	  各设备片段仍以原读数区间起点累计比例向下取整,日界线、查询边界与成员
107	  切换均不重置分摊起点,拆开查询相加一致。每天显示生效成员及其时段、估算
108	  消耗与有效/异常/未知秒数(三者之和等于当天查询时长);有异常或未知标为
109	  不完整,无有效覆盖显示无法计算。配置不改读数、规则和告警,导入不改配置。
110	
111	修正与撤销(correct / undo / corrections):
112	  correct 一次提交指定非空请求标识(--request,去首尾空白、区分大小写,在
113	  数据目录内唯一)及至少一个 --item 修正项;每项 --device、--at、--expect、
114	  --set 各恰好一个,给出设备、实际时刻(秒精度 ISO8601 带 Z 或数字时区
115	  偏移)、预期原读数和替换读数(均为非负、最多三位小数 kWh,任意大数精确)。
116	  只修改已有读数的累计值,不新增或删除读数;同批同一读数身份(设备+实际
117	  时刻)只允许一项;替换值可等于原值,但仍须核验预期原值。首次提交逐项把
118	  预期原值与操作前已存值精确比较,全部匹配才整体替换,成功报告请求标识与
119	  实际改变数;任一项身份不存在或原值不符均指出原因、整批拒绝,不改变其他
120	  项,也不占用请求标识(失败后可修改内容用同一标识重新提交)。读数替换与
121	  请求成功记录同时持久化,写入失败保留操作前全部状态。同标识、同修正内容
122	  重放直接返回原成功结果,不重新校验当前读数、不再次替换(即使这些读数
123	  后来又被其他请求修正,或本修正后来被撤销);修正项顺序、等价时区及等价
124	  十进制写法不影响内容等价性;同标识异内容报冲突且保持状态。
125	  undo 一次提交指定非空撤销请求标识(--request)及目标修正请求标识
126	  (--target),整批撤销一次已成功修正,不允许挑选部分项;目标只能是成功
127	  修正,不能是撤销请求,未知或已撤销目标报错。撤销与修正请求共用唯一标识
128	  空间,成功标识绑定操作类型和内容。首次撤销只恢复目标中实际改变过的读数,
129	  将其还原为该修正记录的原值,不新增或删除读数;每个待恢复身份必须存在、
130	  当前值精确等于原替换值,且没有后来尚未撤销、实际改变过该读数的修正
131	  (后来改回相同数值也不能绕过来源检查,相关后续修正先撤销后才能再撤销
132	  较早请求)。同值项不恢复、不阻塞;全部为同值项的目标仍可成功撤销,恢复
133	  数为零。任一项不满足条件指出身份和原因、整次拒绝,不占用撤销标识。同
134	  撤销标识、同目标重放返回原成功结果,不重新核验、不重复恢复;同标识异
135	  目标或跨操作类型复用标识均报冲突。读数恢复与撤销成功记录同时原子持久化,
136	  重启后状态与来源判断一致。成功报告撤销请求、目标和恢复数,原修正内容
137	  保留并标记已撤销。corrections 按成功提交顺序显示各修正请求及各项设备、
138	  时刻、原值和替换值,另按成功发生顺序显示撤销请求与目标关系,只读。
139	  修正与撤销后 readings、daily、group daily 与 alerts 的当前消耗按新相邻
140	  区间重算;分组成员、规则与告警记录不变,检测状态仍需显式 evaluate 更新;
141	  后续 import 按当前读数判重与冲突,并保留修正与撤销历史。
142	
143	告警规则(rule / evaluate / alerts / ack):
144	  规则标识非空且在设备与分组两类规则间唯一(去首尾空白、区分大小写);用
145	  --device 绑定一个已有存储读数的设备,或用 --group 绑定一个已有分组(二者
146	  恰好其一);设备与分组即使同名也是不同目标,列表与历史均显示目标类型。
147	  阈值非负、最多三位小数 kWh;目标、阈值与时区创建后固定,分组规则绑定分组
148	  标识、不冻结创建时成员。--tz 可选,接受运行环境支持的 IANA 时区名(如
149	  Asia/Shanghai、America/New_York),省略为 UTC(与显式 UTC 等价);时区按
150	  运行环境解析后的规范名存储与比较,未知时区名为参数错误,返回 2。相同标识、
151	  同目标类型、同目标标识、等价阈值及同时区重试成功且不重复创建,任一不同
152	  即报冲突。
153	  evaluate 与 alerts 的 --from/--to 为 YYYY-MM-DD 的当地日期(按规则时区
154	  解释),起日含、止日不含,起日必须更早。每个日期统计归属该日期的全部实际
155	  UTC 时段,不把当地午夜套用固定偏移:夏令时短日不补未知,回拨重复小时完整
156	  计入,日期回退的不连续时段合并为同一天、一次评估只作一次判定;整日被跳过
157	  的日期标明跳过,不判定、不创建也不恢复告警。设备规则评估口径与 daily 相同;
158	  分组规则与 group daily 的联合覆盖口径相同:每天按当时生效的成员版本计算,
159	  允许日内切换,首个版本生效前为未知,任一成员下降为异常,否则任一成员未知
160	  为未知;成员切换不重置各设备原读数区间的分摊起点。仅全天有效覆盖的日期
161	  可判定,消耗严格大于阈值才超限(等于为正常),零增长有效;有未知或下降
162	  覆盖的日期不可判定,不触发也不恢复。每个规则每个日期独立跟踪:首次超限
163	  创建带全局唯一标识的未确认告警,重复超限保留原标识;完整评估正常才记录
164	  恢复;恢复后再超限创建新的未确认告警,旧记录保留,原确认不转移。批量日期
165	  评估要么全部提交要么不提交。
166	  ack 按告警标识确认,已恢复告警也可确认;重复确认成功且不重复记事,确认
167	  不改变超限或恢复状态。alerts 按规则和当地日期升序展示当前计算的消耗或不
168	  可判定原因、实际 UTC 时段及有效/异常/未知秒数、各次告警的标识、检测状态、
169	  确认状态及按发生顺序排列的触发/恢复/确认事件(触发、恢复时的消耗为当时
170	  记录,不随后续数据改写);省略日期范围时展示有告警记录的全部日期;查询
171	  只读,不会隐式恢复。导入读数或补录成员版本都不自动评估,需显式重评才更新
172	  检测状态。规则时区与历史重启后保留;没有时区的旧规则按 UTC 使用,原告警
173	  标识、日期、状态和事件顺序保留。
174	
175	CSV 格式:
176	  表头: ${CSV_HEADER}
177	  device   设备标识(区分大小写,首尾空白忽略,去空白后不能为空)
178	  time     秒精度 ISO8601,带 Z 或数字时区偏移;必须是真实日期
179	  reading  累计电表读数(kWh,非负,最多三位小数;可超出 Number 安全整数
180	           范围,任意大的十进制值都精确保存,如 9007199254740.991)
181	  支持标准双引号字段与 "" 转义;同一设备同一时刻(按实际时刻判定)
182	  重复且数值相同记为重复跳过,数值不同视为冲突并拒绝整批。
183	
184	数值精度:
185	  读数与阈值以毫千瓦时 BigInt 运算,解析、求差、分摊、汇总、比较、保存
186	  和显示全程精确,输出固定三位小数,不使用科学计数法。
187	  兼容旧版 readings.json / alerts.json 中以 JSON 数值保存的安全整数
188	  读数与阈值,无需手工转换;新版以十进制字符串保存。数值型毫千瓦时若
189	  已超出安全整数范围(精度已丢失)按损坏数据拒绝,不猜测原值。
190	
191	数据位置:
192	  $METERWATCH_DATA_DIR/readings.json(默认 ~/.meterwatch/readings.json;
193	           读数与修正、撤销历史同文件保存,旧版无修正与撤销历史的文件可直接使用)
194	  $METERWATCH_DATA_DIR/alerts.json(告警规则与历史,与读数文件相互独立)
195	  $METERWATCH_DATA_DIR/groups.json(分组配置,与读数、告警文件相互独立)
196	
197	退出码: 0 成功;1 数据或读写错误;2 参数错误`;
198	
199	function usageError(message: string): number {
200	  console.error(`${name}: ${message}`);
201	  console.error(`用法见 'node app.ts --help'`);
202	  return 2;
203	}
204	
205	interface ParsedOptions {
206	  devices: string[];
207	  from?: number;
208	  to?: number;
209	  tz?: string;
210	}
211	
212	/** 解析 --device/--from/--to(及允许时的 --tz)选项;出错返回错误消息字符串。 */
213	function parseOptions(rest: string[], allowTz = false): ParsedOptions | string {
214	  const devices: string[] = [];
215	  let from: number | undefined;
216	  let to: number | undefined;
217	  let tz: string | undefined;
218	  for (let i = 0; i < rest.length; i++) {
219	    let opt = rest[i];
220	    let value: string | undefined;
221	    const eq = opt.indexOf('=');
222	    if (opt.startsWith('--') && eq !== -1) {
223	      value = opt.slice(eq + 1);
224	      opt = opt.slice(0, eq);
225	    } else if (opt.startsWith('--')) {
226	      value = rest[i + 1];
227	      if (value === undefined) return `选项 '${opt}' 缺少值`;
228	      i++;
229	    } else {
230	      return `无法识别的参数 '${opt}'`;
231	    }
232	    if (opt === '--device') {
233	      if (value.trim() === '') return "'--device' 的值不能为空";
234	      devices.push(value);
235	    } else if (opt === '--from' || opt === '--to') {
236	      const ts = parseIso8601(value.trim());
237	      if (ts === null) {
238	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
239	      }
240	      if (opt === '--from') from = ts;
241	      else to = ts;
242	    } else if (opt === '--tz' && allowTz) {
243	      tz = value.trim();
244	      if (tz === '') return "'--tz' 的值不能为空";
245	    } else {
246	      return `无法识别的选项 '${opt}'`;
247	    }
248	  }
249	  return { devices, from, to, tz };
250	}
251	
252	/** 校验 IANA 分日时区名;无效时返回错误消息字符串。 */
253	function checkTz(tz: string): string | null {
254	  if (loadTimezone(tz) === null) {
255	    return `未知时区 '${tz}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`;
256	  }
257	  return null;
258	}
259	
260	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
261	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
262	  const out = new Map<string, string[]>();
263	  for (let i = 0; i < rest.length; i++) {
264	    let opt = rest[i];
265	    let value: string | undefined;
266	    const eq = opt.indexOf('=');
267	    if (opt.startsWith('--') && eq !== -1) {
268	      value = opt.slice(eq + 1);
269	      opt = opt.slice(0, eq);
270	    } else if (opt.startsWith('--')) {
271	      value = rest[i + 1];
272	      if (value === undefined) return `选项 '${opt}' 缺少值`;
273	      i++;
274	    } else {
275	      return `无法识别的参数 '${opt}'`;
276	    }
277	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
278	    const list = out.get(opt);
279	    if (list) list.push(value);
280	    else out.set(opt, [value]);
281	  }
282	  return out;
283	}
284	
285	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
286	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
287	  const list = flags.get(name);
288	  if (!list || list.length !== 1) return null;
289	  return list[0];
290	}
291	
292	/** 解析 YYYY-MM-DD 日期选项为当地日期标签;无效时返回错误消息字符串。 */
293	function dateFlag(value: string, label: string): { date: string } | string {
294	  const v = value.trim();
295	  if (parseUtcDate(v) === null) {
296	    return `${label}无效: '${v}'(需 YYYY-MM-DD 的真实日期)`;
297	  }
298	  return { date: v };
299	}
300	
301	function cmdRule(rest: string[]): number {
302	  const [sub, ...subrest] = rest;
303	  if (sub === 'list') {
304	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
305	    return cmdRuleList();
306	  }
307	  if (sub === 'create') {
308	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold', '--tz']);
309	    if (typeof flags === 'string') return usageError(flags);
310	    const idRaw = oneFlag(flags, '--id');
311	    const deviceList = flags.get('--device');
312	    const groupList = flags.get('--group');
313	    const thresholdRaw = oneFlag(flags, '--threshold');
314	    const tzList = flags.get('--tz');
315	    if (idRaw === null || thresholdRaw === null) {
316	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
317	    }
318	    if (tzList !== undefined && tzList.length !== 1) {
319	      return usageError("'rule create' 的 --tz 只能出现一次");
320	    }
321	    const hasDevice = deviceList !== undefined;
322	    const hasGroup = groupList !== undefined;
323	    if (hasDevice === hasGroup) {
324	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
325	    }
326	    if ((deviceList !== undefined && deviceList.length !== 1) ||
327	      (groupList !== undefined && groupList.length !== 1)) {
328	      return usageError("'rule create' 的目标选项只能出现一次");
329	    }
330	    const id = idRaw.trim();
331	    if (id === '') return usageError('规则标识不能为空');
332	    const thresholdMilli = parseKwh(thresholdRaw.trim());
333	    if (thresholdMilli === null) {
334	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
335	    }
336	    // 时区省略与显式 UTC 等价;按运行环境解析后的规范名存储与比较。
337	    let tz = 'UTC';
338	    if (tzList !== undefined) {
339	      const tzRaw = tzList[0].trim();
340	      if (tzRaw === '') return usageError("'--tz' 的值不能为空");
341	      const canonical = canonicalTimezone(tzRaw);
342	      if (canonical === null) {
343	        return usageError(`未知时区 '${tzRaw}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`);
344	      }
345	      tz = canonical;
346	    }
347	    if (hasDevice) {
348	      const device = (deviceList as string[])[0].trim();
349	      if (device === '') return usageError("'--device' 的值不能为空");
350	      return cmdRuleCreate({ id, targetType: 'device', targetId: device, thresholdMilli, tz });
351	    }
352	    const group = (groupList as string[])[0].trim();
353	    if (group === '') return usageError("'--group' 的值不能为空");
354	    return cmdRuleCreate({ id, targetType: 'group', targetId: group, thresholdMilli, tz });
355	  }
356	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
357	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
358	}
359	
360	function cmdEvaluateEntry(rest: string[]): number {
361	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
362	  if (typeof flags === 'string') return usageError(flags);
363	  const ruleRaw = oneFlag(flags, '--rule');
364	  const fromRaw = oneFlag(flags, '--from');
365	  const toRaw = oneFlag(flags, '--to');
366	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
367	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
368	  }
369	  const ruleId = ruleRaw.trim();
370	  if (ruleId === '') return usageError('规则标识不能为空');
371	  const from = dateFlag(fromRaw, '起始日期');
372	  if (typeof from === 'string') return usageError(from);
373	  const to = dateFlag(toRaw, '结束日期');
374	  if (typeof to === 'string') return usageError(to);
375	  if (from.date >= to.date) return usageError('评估起日必须早于止日(--from < --to)');
376	  return cmdEvaluate({ ruleId, from: from.date, to: to.date });
377	}
378	
379	function cmdAlertsEntry(rest: string[]): number {
380	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
381	  if (typeof flags === 'string') return usageError(flags);
382	  const ruleRaw = oneFlag(flags, '--rule');
383	  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
384	  const ruleId = ruleRaw.trim();
385	  if (ruleId === '') return usageError('规则标识不能为空');
386	  const fromList = flags.get('--from');
387	  const toList = flags.get('--to');
388	  if ((fromList !== undefined) !== (toList !== undefined)) {
389	    return usageError("'alerts' 的 --from 与 --to 需同时提供或同时省略");
390	  }
391	  let from: string | undefined;
392	  let to: string | undefined;
393	  if (fromList !== undefined) {
394	    const fromRaw = oneFlag(flags, '--from');
395	    const toRaw = oneFlag(flags, '--to');
396	    if (fromRaw === null || toRaw === null) {
397	      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
398	    }
399	    const fromParsed = dateFlag(fromRaw, '起始日期');
400	    if (typeof fromParsed === 'string') return usageError(fromParsed);
401	    const toParsed = dateFlag(toRaw, '结束日期');
402	    if (typeof toParsed === 'string') return usageError(toParsed);
403	    if (fromParsed.date >= toParsed.date) return usageError('查询起日必须早于止日(--from < --to)');
404	    from = fromParsed.date;
405	    to = toParsed.date;
406	  }
407	  return cmdAlerts({ ruleId, from, to });
408	}
409	
410	function cmdGroup(rest: string[]): number {
411	  const [sub, ...subrest] = rest;
412	  if (sub === 'configure') {
413	    const flags = parseFlags(subrest, ['--id', '--at', '--device']);
414	    if (typeof flags === 'string') return usageError(flags);
415	    const idRaw = oneFlag(flags, '--id');
416	    const atRaw = oneFlag(flags, '--at');
417	    const deviceList = flags.get('--device') ?? [];
418	    if (idRaw === null || atRaw === null) {
419	      return usageError("'group configure' 需要 --id 与 --at 各恰好一个");
420	    }
421	    if (deviceList.length === 0) {
422	      return usageError("'group configure' 需要至少一个 --device(成员不能为空)");
423	    }
424	    const id = idRaw.trim();
425	    if (id === '') return usageError('分组标识不能为空');
426	    const at = parseIso8601(atRaw.trim());
427	    if (at === null) {
428	      return usageError(
429	        `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`,
430	      );
431	    }
432	    const members: string[] = [];
433	    for (const d of deviceList) {
434	      const m = d.trim();
435	      if (m === '') return usageError("'--device' 的值不能为空");
436	      members.push(m);
437	    }
438	    return cmdGroupConfigure({ id, at, members });
439	  }
440	  if (sub === 'history') {
441	    const flags = parseFlags(subrest, ['--id']);
442	    if (typeof flags === 'string') return usageError(flags);
443	    const idRaw = oneFlag(flags, '--id');
444	    if (idRaw === null) return usageError("'group history' 需要 --id 恰好一个");
445	    const id = idRaw.trim();
446	    if (id === '') return usageError('分组标识不能为空');
447	    return cmdGroupHistory({ id });
448	  }
449	  if (sub === 'daily') {
450	    const flags = parseFlags(subrest, ['--id', '--from', '--to', '--tz']);
451	    if (typeof flags === 'string') return usageError(flags);
452	    const idRaw = oneFlag(flags, '--id');
453	    const fromRaw = oneFlag(flags, '--from');
454	    const toRaw = oneFlag(flags, '--to');
455	    if (idRaw === null || fromRaw === null || toRaw === null) {
456	      return usageError("'group daily' 需要 --id、--from、--to 各恰好一个(起点含、终点不含)");
457	    }
458	    const tzList = flags.get('--tz');
459	    if (tzList !== undefined && tzList.length !== 1) {
460	      return usageError("'group daily' 的 --tz 只能出现一次");
461	    }
462	    const id = idRaw.trim();
463	    if (id === '') return usageError('分组标识不能为空');
464	    const from = parseIso8601(fromRaw.trim());
465	    if (from === null) {
466	      return usageError(`选项 '--from' 的时间无效: '${fromRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
467	    }
468	    const to = parseIso8601(toRaw.trim());
469	    if (to === null) {
470	      return usageError(`选项 '--to' 的时间无效: '${toRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
471	    }
472	    if (from >= to) return usageError('查询起点必须早于终点(--from < --to)');
473	    let tz: string | undefined;
474	    if (tzList !== undefined) {
475	      tz = tzList[0].trim();
476	      if (tz === '') return usageError("'--tz' 的值不能为空");
477	      const bad = checkTz(tz);
478	      if (bad !== null) return usageError(bad);
479	    }
480	    return cmdGroupDaily({ id, from, to, tz });
481	  }
482	  if (sub === undefined) return usageError("'group' 需要子命令 configure、history 或 daily");
483	  return usageError(`无法识别的 group 子命令 '${sub}'`);
484	}
485	
486	/**
487	 * 解析 correct 的修正项:以裸 '--item' 分段,每段需 --device/--at/--expect/--set
488	 * 各恰好一个。出错返回错误消息字符串。
489	 */
490	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
491	  const segments: string[][] = [[]];
492	  for (const tok of rest) {
493	    if (tok === '--item') segments.push([]);
494	    else segments[segments.length - 1].push(tok);
495	  }
496	  const headFlags = parseFlags(segments[0], ['--request']);
497	  if (typeof headFlags === 'string') return headFlags;
498	  const requestRaw = oneFlag(headFlags, '--request');
499	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
500	  const requestId = requestRaw.trim();
501	  if (requestId === '') return '请求标识不能为空';
502	  const itemSegs = segments.slice(1);
503	  if (itemSegs.length === 0) {
504	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
505	  }
506	  const items: CorrectionItem[] = [];
507	  for (const seg of itemSegs) {
508	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
509	    if (typeof flags === 'string') return flags;
510	    const deviceRaw = oneFlag(flags, '--device');
511	    const atRaw = oneFlag(flags, '--at');
512	    const expectRaw = oneFlag(flags, '--expect');
513	    const setRaw = oneFlag(flags, '--set');
514	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
515	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
516	    }
517	    const device = deviceRaw.trim();
518	    if (device === '') return "'--device' 的值不能为空";
519	    const ts = parseIso8601(atRaw.trim());
520	    if (ts === null) {
521	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
522	    }
523	    const expectedMilli = parseKwh(expectRaw.trim());
524	    if (expectedMilli === null) {
525	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
526	    }
527	    const replacementMilli = parseKwh(setRaw.trim());
528	    if (replacementMilli === null) {
529	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
530	    }
531	    items.push({ device, ts, expectedMilli, replacementMilli });
532	  }
533	  return { requestId, items };
534	}
535	
536	function cmdCorrectEntry(rest: string[]): number {
537	  const parsed = parseCorrectItems(rest);
538	  if (typeof parsed === 'string') return usageError(parsed);
539	  return cmdCorrect(parsed.requestId, parsed.items);
540	}
541	
542	function cmdUndoEntry(rest: string[]): number {
543	  const flags = parseFlags(rest, ['--request', '--target']);
544	  if (typeof flags === 'string') return usageError(flags);
545	  const requestRaw = oneFlag(flags, '--request');
546	  const targetRaw = oneFlag(flags, '--target');
547	  if (requestRaw === null || targetRaw === null) {
548	    return usageError("'undo' 需要 --request 与 --target 各恰好一个");
549	  }
550	  const requestId = requestRaw.trim();
551	  if (requestId === '') return usageError('撤销请求标识不能为空');
552	  const targetId = targetRaw.trim();
553	  if (targetId === '') return usageError('目标修正请求标识不能为空');
554	  return cmdUndo(requestId, targetId);
555	}
556	
557	function main(args: string[]): number {
558	  if (args.length === 0) {
559	    console.log(help);
560	    return 0;
561	  }
562	  const [cmd, ...rest] = args;
563	  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
564	    console.log(help);
565	    return 0;
566	  }
567	
568	  // 上次恢复若在提交中断,先把数据目录恢复为完整旧状态或完整快照状态;
569	  // 无法完成时明确报错,绝不查询或修改混合状态。
570	  const recoveryError = recoverInterruptedRestore();
571	  if (recoveryError !== null) {
572	    console.error(`${name}: ${recoveryError}`);
573	    return 1;
574	  }
575	
576	  if (cmd === 'import') {
577	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
578	    return cmdImport(rest[0]);
579	  }
580	
581	  if (cmd === 'readings') {
582	    const parsed = parseOptions(rest);
583	    if (typeof parsed === 'string') return usageError(parsed);
584	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
585	      return usageError('查询起点必须早于终点(--from < --to)');
586	    }
587	    return cmdReadings(parsed);
588	  }
589	
590	  if (cmd === 'daily') {
591	    const parsed = parseOptions(rest, true);
592	    if (typeof parsed === 'string') return usageError(parsed);
593	    if (parsed.from === undefined || parsed.to === undefined) {
594	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
595	    }
596	    if (parsed.from >= parsed.to) {
597	      return usageError('查询起点必须早于终点(--from < --to)');
598	    }
599	    if (parsed.tz !== undefined) {
600	      const bad = checkTz(parsed.tz);
601	      if (bad !== null) return usageError(bad);
602	    }
603	    return cmdDaily({ devices: parsed.devices, from: parsed.from, to: parsed.to, tz: parsed.tz });
604	  }
605	
606	  if (cmd === 'rule') return cmdRule(rest);
607	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
608	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
609	  if (cmd === 'group') return cmdGroup(rest);
610	  if (cmd === 'correct') return cmdCorrectEntry(rest);
611	  if (cmd === 'undo') return cmdUndoEntry(rest);
612	
613	  if (cmd === 'corrections') {
614	    if (rest.length !== 0) return usageError("'corrections' 不接受参数");
615	    return cmdCorrections();
616	  }
617	
618	  if (cmd === 'ack') {
619	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
620	    const alertId = rest[0].trim();
621	    if (alertId === '') return usageError('告警标识不能为空');
622	    return cmdAck(alertId);
623	  }
624	
625	  if (cmd === 'backup') {
626	    if (rest.length !== 1) return usageError("'backup' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
627	    return cmdBackup(rest[0]);
628	  }
629	
630	  if (cmd === 'restore') {
631	    if (rest.length !== 1) return usageError("'restore' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
632	    return cmdRestore(rest[0]);
633	  }
634	
635	  return usageError(`无法识别的参数 '${cmd}'`);
636	}
637	
638	process.exitCode = main(process.argv.slice(2));
