197	    }
198	  }
199	  return `cannot acquire lock ${join(dir, LOCK_NAME)}`;
200	}
201	
202	function releaseLock(dir: string): void {
203	  try {
204	    rmSync(join(dir, LOCK_NAME));
205	  } catch {
206	    // 锁文件可能已被清理;释放失败不影响已完成的操作。
207	  }
208	}
209	
210	interface JournalFile {
211	  name: string;
212	  hadOld: boolean;
213	}
214	
215	interface Journal {
216	  files: JournalFile[];
217	}
218	
219	/** 解析恢复日志;结构非法返回 null(调用方按无法恢复处理,不猜测)。 */
220	function parseJournal(data: unknown): Journal | null {
221	  const o = data as Record<string, unknown>;
222	  if (
223	    o === null ||
224	    typeof o !== 'object' ||
225	    o.format !== JOURNAL_FORMAT ||
226	    o.version !== 1 ||
227	    !Array.isArray(o.files) ||
228	    o.files.length === 0
229	  ) {
230	    return null;
231	  }
232	  const files: JournalFile[] = [];
233	  for (const f of o.files as Array<Record<string, unknown>>) {
234	    if (
235	      f === null ||
236	      typeof f !== 'object' ||
237	      typeof f.name !== 'string' ||
238	      f.name.length === 0 ||
239	      typeof f.hadOld !== 'boolean'
240	    ) {
241	      return null;
242	    }
243	    files.push({ name: f.name, hadOld: f.hadOld });
244	  }
245	  return { files };
246	}
247	
248	/**
249	 * 回滚到恢复前状态:凡有旧文件备份的换回原文件,原本不存在的文件删除新文件;
250	 * 清理临时文件与日志。任何一步失败抛错。
251	 */
252	function rollback(dir: string, journal: Journal): void {
253	  for (const f of journal.files) {
254	    const target = join(dir, f.name);
255	    const oldPath = target + OLD_SUFFIX;
256	    const newPath = target + NEW_SUFFIX;
257	    if (existsSync(oldPath)) {
258	      // 旧文件备份必为常规文件(本进程只会写出常规文件);否则按被篡改处理,不猜测。
259	      if (!statSync(oldPath).isFile()) {
260	        throw new StoreError(`restore backup ${oldPath} is not a regular file`);
261	      }
262	      if (existsSync(target)) rmSync(target);
263	      renameSync(oldPath, target);
264	    } else if (!f.hadOld && !existsSync(newPath) && existsSync(target)) {
265	      // 新文件已被换入且原本不存在:删除以恢复原状。
266	      rmSync(target);
267	    } else if (f.hadOld && !existsSync(target)) {
268	      // 日志称原有旧文件,但旧备份与原文件都不在:状态不一致,不猜测。
269	      throw new StoreError(`cannot roll back ${target}: both the original and its backup are missing`);
270	    }
271	  }
272	  for (const f of journal.files) {
273	    const newPath = join(dir, f.name) + NEW_SUFFIX;
274	    if (existsSync(newPath)) {
275	      try {
276	        rmSync(newPath);
277	      } catch {
278	        // 残留的临时文件不影响业务状态,下次启动再清理。
279	      }
280	    }
281	  }
282	  rmSync(join(dir, JOURNAL_NAME));
283	}
284	
285	/**
286	 * 前滚到完整快照状态:把仍待换入的新文件换入,删除日志与旧文件备份。
287	 * 任何一步失败抛错。
288	 */
289	function rollForward(dir: string, journal: Journal): void {
290	  for (const f of journal.files) {
291	    const newPath = join(dir, f.name) + NEW_SUFFIX;
292	    if (existsSync(newPath)) {
293	      // 待换入的新内容必为常规文件(本进程只会写出常规文件);否则按被篡改
294	      // 处理,中止前滚,由调用方回退或报错,绝不把异常内容当作业务存储。
295	      if (!statSync(newPath).isFile()) {
296	        throw new StoreError(`restore temp file ${newPath} is not a regular file`);
297	      }
298	      renameSync(newPath, join(dir, f.name));
299	    }
300	  }
301	  // 前滚完成后每个业务存储都必须就位;缺失说明状态被外部破坏,中止并交由
302	  // 调用方回退或报错,绝不删除旧文件备份。
303	  for (const f of journal.files) {
304	    if (!existsSync(join(dir, f.name))) {
305	      throw new StoreError(`restore temp file for ${f.name} is missing; cannot complete the commit`);
306	    }
307	  }
308	  rmSync(join(dir, JOURNAL_NAME));
309	  for (const f of journal.files) {
310	    const oldPath = join(dir, f.name) + OLD_SUFFIX;
311	    if (existsSync(oldPath)) rmSync(oldPath);
312	  }
313	}
314	
315	/**
316	 * 任一命令启动时调用:若上次恢复在提交中断,先把数据目录恢复为完整快照
317	 * 状态(优先)或完整旧状态,绝不留下混合状态。成功(或无需恢复)返回 null,
318	 * 无法完成返回错误消息。
319	 */
320	export function recoverInterruptedRestore(): string | null {
321	  const dir = dataDirPath();
322	  const journalPath = join(dir, JOURNAL_NAME);
323	  if (existsSync(journalPath)) {
324	    let journal: Journal | null = null;
325	    try {
326	      journal = parseJournal(JSON.parse(readFileSync(journalPath, 'utf8')));
327	    } catch {
328	      journal = null;
329	    }
330	    if (journal === null) {
331	      return (
332	        `cannot recover data directory ${dir}: restore journal ${journalPath} is unreadable or invalid; ` +
333	        `the directory may hold a mixed state, restore it manually from a snapshot`
334	      );
335	    }
336	    try {
337	      rollForward(dir, journal);
338	      console.error('meterwatch: completed an interrupted restore: snapshot state committed');
339	      return null;
340	    } catch {
341	      // 前滚失败则尝试回滚为完整旧状态。
342	    }
343	    try {
344	      rollback(dir, journal);
345	      console.error('meterwatch: rolled back an interrupted restore: previous state preserved');
346	      return null;
347	    } catch (e) {
348	      return (
349	        `cannot recover data directory ${dir} to a consistent state: ${(e as Error).message}; ` +
350	        `restore it manually from a snapshot`
351	      );
352	    }
353	  }
354	  // 无日志:提交要么未开始(可能残留新临时文件),要么已完整完成(可能残留旧文件
355	  // 备份);两种残留都不影响业务状态,清理即可。清理失败明确报错,不继续启动。
356	  for (const path of storeFiles()) {
357	    for (const leftover of [path + NEW_SUFFIX, path + OLD_SUFFIX]) {
358	      if (existsSync(leftover)) {
359	        try {
360	          rmSync(leftover);
361	        } catch (e) {
362	          return `cannot clean up interrupted restore leftover ${leftover}: ${(e as Error).message}`;
363	        }
364	      }
365	    }
366	  }
367	  return null;
368	}
369	
370	/**
371	 * 把三个业务存储的新内容作为一次恢复提交。失败抛 StoreError 并尽力回滚为
372	 * 提交前状态;回滚也失败时错误中明确说明目录可能处于混合状态。
373	 */
374	function commitRestore(dir: string, files: Array<{ path: string; body: string }>): void {
375	  const journalPath = join(dir, JOURNAL_NAME);
376	  const journal: Journal = {
377	    files: files.map((f) => ({ name: basename(f.path), hadOld: existsSync(f.path) })),
378	  };
379	
380	  // 阶段一:写全部新内容到临时文件,再原子写入恢复日志。此阶段失败或中断
381	  // 不影响现有业务文件;残留的临时文件由下次启动清理。
382	  try {
383	    for (const f of files) {
384	      writeFileSync(f.path + NEW_SUFFIX, f.body, 'utf8');
385	    }
386	    const journalTmp = `${journalPath}.tmp-${process.pid}`;
387	    writeFileSync(
388	      journalTmp,
389	      JSON.stringify({ format: JOURNAL_FORMAT, version: 1, files: journal.files }, null, 2) + '\n',
390	      'utf8',
391	    );
392	    renameSync(journalTmp, journalPath);
393	  } catch (e) {
394	    for (const f of files) {
395	      try {
396	        rmSync(f.path + NEW_SUFFIX);
397	      } catch {
398	        // 清理失败不掩盖原始错误。
399	      }
400	    }
401	    throw new StoreError(`cannot prepare restore in ${dir}: ${(e as Error).message}; nothing was changed`);
402	  }
403	
404	  // 阶段二:整体换名提交(旧文件换为备份,新文件换入),然后删除日志与备份。
405	  // 此阶段中断由下次启动按日志前滚或回滚;受控失败按已完成的步骤精确回滚
406	  // (只动本次自己换名的文件,不触碰目录内任何其他文件)。
407	  const movedToOld: string[] = [];
408	  const movedIn: string[] = [];
409	  try {
410	    for (const f of files) {
411	      if (existsSync(f.path)) {
412	        renameSync(f.path, f.path + OLD_SUFFIX);
413	        movedToOld.push(f.path);
414	      }
415	    }
416	    for (const f of files) {
417	      renameSync(f.path + NEW_SUFFIX, f.path);
418	      movedIn.push(f.path);
419	    }
420	    rmSync(journalPath);
421	    for (const f of files) {
422	      if (existsSync(f.path + OLD_SUFFIX)) rmSync(f.path + OLD_SUFFIX);
423	    }
424	  } catch (e) {
425	    try {
426	      // 撤销已换入的新文件,再把已换出的旧文件换回原位;未完成的步骤不动。
427	      for (const path of movedIn) {
428	        if (existsSync(path)) rmSync(path);
429	      }
430	      for (const path of movedToOld) {
431	        renameSync(path + OLD_SUFFIX, path);
432	      }
433	      for (const f of files) {
434	        if (existsSync(f.path + NEW_SUFFIX)) rmSync(f.path + NEW_SUFFIX);
435	      }
436	      rmSync(journalPath);
437	    } catch (re) {
438	      throw new StoreError(
439	        `restore failed (${(e as Error).message}) and rollback also failed (${(re as Error).message}); ` +
440	          `data directory ${dir} may be in a mixed state, restore it manually from a snapshot`,
441	      );
442	    }
443	    throw new StoreError(`restore failed: ${(e as Error).message}; previous state preserved`);
444	  }
445	}
446	
447	/** 各存储内容汇总的一行数量报告。 */
448	function countsReport(data: StoreData, alerts: AlertState, groups: Group[]): string {
449	  const versions = groups.reduce((n, g) => n + g.versions.length, 0);
450	  return (
451	    `${data.readings.length} reading(s), ${data.corrections.length} correction(s), ` +
452	    `${data.undos.length} undo(s), ${groups.length} group(s) (${versions} member version(s)), ` +
453	    `${alerts.rules.length} rule(s), ${alerts.alerts.length} alert(s)`
454	  );
455	}
456	
457	/**
458	 * 导出全库快照。只读取业务存储,不改写业务数据;输出文件必须位于数据目录
459	 * 之外且不得已存在。返回进程退出码。
460	 */
461	export function cmdBackup(outPath: string): number {
462	  const dir = dataDirPath();
463	  if (isInsideDir(dir, outPath)) {
464	    err(`snapshot file '${outPath}' must be located outside the data directory ${dir}`);
465	    return 2;
466	  }
467	
468	  mkdirSync(dir, { recursive: true });
469	  const lockError = acquireLock(dir);
470	  if (lockError !== null) {
471	    err(lockError);
472	    return 1;
473	  }
474	  try {
475	    let data: StoreData;
476	    let alerts: AlertState;
477	    let groups: Group[];
478	    try {
479	      data = loadData(dataFilePath());
480	      alerts = loadAlertState(alertFilePath());
481	      groups = loadGroups(groupFilePath());
482	    } catch (e) {
483	      if (e instanceof StoreError) {
484	        err(e.message);
485	        return 1;
486	      }
487	      throw e;
488	    }
489	
490	    const problems = validateStores(data, alerts, groups);
491	    if (problems.length > 0) {
492	      for (const p of problems) err(p);
493	      err(`backup rejected: ${problems.length} consistency problem(s); no snapshot was written`);
494	      return 1;
495	    }
496	
497	    const payload = {
498	      readings: serializeStoreData(data),
499	      alerts: serializeAlertState(alerts),
500	      groups: serializeGroups(groups),
501	    };
502	    const checksum = createHash('sha256').update(JSON.stringify(payload), 'utf8').digest('hex');
503	    const body =
504	      JSON.stringify(
505	        {
506	          format: SNAPSHOT_FORMAT,
507	          version: SNAPSHOT_VERSION,
508	          checksum: `sha256:${checksum}`,
509	          payload,
510	        },
511	        null,
512	        2,
513	      ) + '\n';
514	
515	    // 先写临时文件,再原子链接为最终名:已存在的输出拒绝覆盖,失败不留下
516	    // 可被当作成功快照的输出。
517	    const out = resolve(outPath);
518	    const tmp = `${out}.tmp-${process.pid}`;
519	    try {
520	      writeFileSync(tmp, body, 'utf8');
521	      linkSync(tmp, out);
522	    } catch (e) {
523	      if ((e as NodeJS.ErrnoException).code === 'EEXIST') {
524	        err(`output file '${outPath}' already exists; refusing to overwrite`);
525	      } else {
526	        err(`cannot write snapshot '${outPath}': ${(e as Error).message}`);
527	      }
528	      return 1;
529	    } finally {
530	      try {
531	        rmSync(tmp);
532	      } catch {
533	        // 临时文件可能未创建;清理失败不影响结果。
534	      }
535	    }
536	
537	    console.log(`snapshot written to '${outPath}': ${countsReport(data, alerts, groups)}`);
538	    return 0;
539	  } finally {
540	    releaseLock(dir);
541	  }
542	}
543	
544	/**
545	 * 从快照整库恢复。快照须通过格式版本与完整性校验,且三个业务存储的结构与
546	 * 关联一致,否则不开始替换。成功后业务状态完全等于快照。返回进程退出码。
547	 */
548	export function cmdRestore(snapshotPath: string): number {
549	  const dir = dataDirPath();
550	  if (isInsideDir(dir, snapshotPath)) {
551	    err(`snapshot file '${snapshotPath}' must be located outside the data directory ${dir}`);
552	    return 2;
553	  }
554	
555	  let text: string;
556	  try {
557	    text = readFileSync(resolve(snapshotPath), 'utf8');
558	  } catch (e) {
559	    err(`cannot read snapshot '${snapshotPath}': ${(e as Error).message}`);
560	    return 1;
561	  }
562	  let envelope: unknown;
563	  try {
564	    envelope = JSON.parse(text);
565	  } catch {
566	    err(`snapshot '${snapshotPath}' is corrupted (invalid JSON or truncated); nothing was restored`);
567	    return 1;
568	  }
569	  const env = envelope as Record<string, unknown>;
570	  if (env === null || typeof env !== 'object' || env.format !== SNAPSHOT_FORMAT) {
571	    err(`snapshot '${snapshotPath}' is not a meterwatch snapshot; nothing was restored`);
572	    return 1;
573	  }
574	  if (env.version !== SNAPSHOT_VERSION) {
575	    err(
576	      `snapshot '${snapshotPath}' has unsupported format version ${String(env.version)} ` +
577	        `(this build supports version ${SNAPSHOT_VERSION}); nothing was restored`,
578	    );
579	    return 1;
580	  }
581	  const payloadText = JSON.stringify(env.payload) ?? '';
582	  const checksum = createHash('sha256').update(payloadText, 'utf8').digest('hex');
583	  if (typeof env.checksum !== 'string' || env.checksum !== `sha256:${checksum}`) {
584	    err(`snapshot '${snapshotPath}' failed its integrity check; nothing was restored`);
585	    return 1;
586	  }
587	
588	  const payload = env.payload as Record<string, unknown>;
589	  let data: StoreData;
590	  let alerts: AlertState;
591	  let groups: Group[];
592	  try {
593	    data = parseStoreData(payload?.readings, `snapshot '${snapshotPath}' readings store`);
594	    alerts = parseAlertState(payload?.alerts, `snapshot '${snapshotPath}' alerts store`);
595	    groups = parseGroups(payload?.groups, `snapshot '${snapshotPath}' groups store`);
596	  } catch (e) {
597	    if (e instanceof StoreError) {
598	      err(`${e.message}; nothing was restored`);
599	      return 1;
600	    }
601	    throw e;
602	  }
603	  const problems = validateStores(data, alerts, groups);
604	  if (problems.length > 0) {
605	    for (const p of problems) err(p);
606	    err(`restore rejected: snapshot has ${problems.length} consistency problem(s); nothing was restored`);
607	    return 1;
608	  }
609	
610	  mkdirSync(dir, { recursive: true });
611	  const lockError = acquireLock(dir);
612	  if (lockError !== null) {
613	    err(lockError);
614	    return 1;
615	  }
616	  try {
617	    commitRestore(dir, [
618	      { path: dataFilePath(), body: JSON.stringify(serializeStoreData(data), null, 2) + '\n' },
619	      { path: alertFilePath(), body: JSON.stringify(serializeAlertState(alerts), null, 2) + '\n' },
620	      { path: groupFilePath(), body: JSON.stringify(serializeGroups(groups), null, 2) + '\n' },
621	    ]);
622	  } catch (e) {
623	    if (e instanceof StoreError) {
624	      err(e.message);
625	      return 1;
626	    }
627	    throw e;
628	  } finally {
629	    releaseLock(dir);
630	  }
631	
632	  console.log(`restored from snapshot '${snapshotPath}': ${countsReport(data, alerts, groups)}`);
633	  return 0;
634	}
