```ts
function dispatch(args: string[]): number { ...current main body minus recovery... }

function main(args: string[]): number {
  // 所有命令入口(含无参数、--help 与非法参数)都先取得数据目录操作权并完成
  // 中断恢复的协调,再执行查询或写入;协调失败返回 1,不触碰业务存储。
  const coordError = acquireDataDir();
  if (coordError !== null) {
    console.error(`${name}: ${coordError}`);
    return 1;
  }
  try {
    const recoveryError = recoverInterruptedRestore();
    if (recoveryError !== null) {
      console.error(`${name}: ${recoveryError}`);
      return 1;
    }
    return dispatch(args);
  } finally {
    releaseDataDir();
  }
}
```

